{
  "name": "opencode-v2-axonhub",
  "version": "0.3.1",
  "description": "OpenCode V2 plugin for discovering AxonHub models",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/zsxsoft/opencode-axonhub"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "axonhub",
    "llm"
  ],
  "files": [
    "src",
    "server.ts",
    "README.md",
    "LICENSE",
    "package.json"
  ],
  "publishConfig": {
    "access": "public"
  },
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./server": "./src/index.ts"
  },
  "types": "./src/index.ts",
  "peerDependencies": {
    "@opencode/plugin": "*"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.14",
    "@types/node": "^22.18.10",
    "typescript": "^5.9.3"
  },
  "scripts": {
    "check": "tsc --noEmit"
  }
}
